-- Pawcast 2026 주문 중심 개발용 더미데이터
-- 전제: pawcast_init.sql 실행 직후의 빈 DB
-- 원본: pawcast_seed_3y.sql에서 2026-01-01 ~ 2026-11-20 주문 및 FK 의존 데이터만 추출
-- 포함: 참조 회원/카테고리/상품/옵션, 주문, 주문항목, 결제, 환불, 배송, 구매리뷰
-- 제외: 2023~2025 주문 및 주문과 무관한 찜/장바구니/반려동물/공지/문의
\set ON_ERROR_STOP on
SET client_encoding TO 'UTF8';
BEGIN;

-- members: 1,541 rows

-- categories: 48 rows

-- products: 2,168 rows

-- product_images: 2,168 rows

-- food_details: 1,921 rows

-- device_details: 247 rows

-- product_pet_types: 2,415 rows

-- product_variants: 5,445 rows

-- orders: 12,275 rows

-- order_items: 18,422 rows

-- payments: 12,275 rows

-- refunds: 382 rows

-- shipments: 11,741 rows

-- product_reviews: 4,436 rows

-- review_images: 1,023 rows

-- 주문·상품 집계값을 실제 적재 레코드로 계산합니다.
UPDATE product_variants v
SET sales_count = COALESCE((
  SELECT SUM(oi.quantity)
  FROM order_items oi
  JOIN orders o ON o.id = oi.order_id
  WHERE oi.product_variant_id = v.id AND o.status <> 'CANCELLED'
), 0);

UPDATE products p
SET sales_count = COALESCE((SELECT SUM(v.sales_count) FROM product_variants v WHERE v.product_id = p.id), 0),
    review_count = (SELECT COUNT(*) FROM product_reviews r WHERE r.product_id = p.id),
    rating_sum = COALESCE((SELECT SUM(r.rating) FROM product_reviews r WHERE r.product_id = p.id), 0);

-- 명시적으로 넣은 ID 뒤로 identity 시퀀스를 전진합니다.
DO $$
DECLARE t record; sequence_name text; maximum bigint;
BEGIN
  FOR t IN SELECT table_name FROM information_schema.columns
           WHERE table_schema = 'public' AND column_name = 'id' AND is_identity = 'YES'
  LOOP
    sequence_name := pg_get_serial_sequence(format('public.%I', t.table_name), 'id');
    EXECUTE format('SELECT max(id) FROM public.%I', t.table_name) INTO maximum;
    IF maximum IS NOT NULL THEN
      PERFORM setval(sequence_name, maximum, true);
    END IF;
  END LOOP;
END $$;

COMMIT;

-- 적재 검수: 모두 0이면 정상입니다.
SELECT 'orders_outside_2026' AS check_name, COUNT(*) AS violations
FROM orders
WHERE created_at < DATE '2026-01-01' OR created_at >= DATE '2027-01-01'
UNION ALL
SELECT 'order_amount_mismatch', COUNT(*)
FROM orders o
WHERE o.total_amount <> (SELECT SUM(oi.total_price) FROM order_items oi WHERE oi.order_id = o.id)
   OR o.final_amount <> o.total_amount - o.discount_amount + o.shipping_fee
UNION ALL
SELECT 'orphan_order_items', COUNT(*)
FROM order_items oi LEFT JOIN orders o ON o.id = oi.order_id WHERE o.id IS NULL
UNION ALL
SELECT 'orphan_payments', COUNT(*)
FROM payments p LEFT JOIN orders o ON o.id = p.order_id WHERE o.id IS NULL;

SELECT 'members' AS entity, COUNT(*) AS row_count FROM members
UNION ALL SELECT 'categories', COUNT(*) FROM categories
UNION ALL SELECT 'products', COUNT(*) FROM products
UNION ALL SELECT 'product_variants', COUNT(*) FROM product_variants
UNION ALL SELECT 'orders', COUNT(*) FROM orders
UNION ALL SELECT 'order_items', COUNT(*) FROM order_items
UNION ALL SELECT 'payments', COUNT(*) FROM payments
UNION ALL SELECT 'refunds', COUNT(*) FROM refunds
UNION ALL SELECT 'shipments', COUNT(*) FROM shipments
UNION ALL SELECT 'product_reviews', COUNT(*) FROM product_reviews;

